#include "ui_common.h"

#include "roboto_regular.h" // generated by CMake from editor/assets/fonts

#include <app.h>
#include <log.h>

#include <SDL3/SDL.h>
#include <bgfx/bgfx.h>

#include <algorithm>
#include <format>

namespace {

constexpr float kFontSize = 16.0f; // at UI scale 1.0
constexpr int kScreenshotTimeoutFrames = 30;

} // namespace

float clampUiScale(float scale) { return std::clamp(scale, kMinUiScale, kMaxUiScale); }

void loadFont()
{
    ImGui::GetStyle().FontSizeBase = kFontSize;
    ImFontConfig config;
    config.FontDataOwnedByAtlas = false; // static embedded data
    ImFontAtlas* fonts = ImGui::GetIO().Fonts;
    if (!fonts->AddFontFromMemoryTTF(kRobotoRegularTtf, sizeof(kRobotoRegularTtf), kFontSize, &config)) {
        kast::log::error("Failed to load embedded Roboto font, using ImGui default font");
        fonts->AddFontDefault();
    }
}

void disabledTooltip(const char* reason)
{
    if (reason && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
        ImGui::SetTooltip("%s", reason);
}

void UiScale::init(SDL_Window* window)
{
    window_ = window;
    base_ = ImGui::GetStyle();
    apply();
}

void UiScale::onEvent(const SDL_Event& event)
{
    if (event.type == SDL_EVENT_WINDOW_DISPLAY_SCALE_CHANGED && !forced_)
        apply();
}

void UiScale::apply()
{
    const float scale = forced_ ? *forced_ : clampUiScale(displayScale());
    if (scale == current_) // SDL can report an unchanged scale, e.g. once at startup
        return;
    current_ = scale;
    ImGuiStyle& style = ImGui::GetStyle();
    style = base_;
    style.ScaleAllSizes(scale);
    style.FontScaleDpi = scale;
    kast::log::info(std::format("UI scale {:.2f} ({})", scale, forced_ ? "--ui-scale" : "display"));
}

float UiScale::displayScale() const
{
    const float scale = SDL_GetWindowDisplayScale(window_);
    if (scale > 0.0f)
        return scale;
    kast::log::error(std::format("SDL_GetWindowDisplayScale failed: {}", SDL_GetError()));
    return 1.0f;
}

void FrameLimit::endFrame()
{
    ++frame_;
    if (frames_ == 0 || frame_ < frames_)
        return;
    if (screenshot_.empty()) {
        if (frame_ == frames_)
            kast::requestQuit();
    } else if (!requested_) {
        bgfx::requestScreenShot(BGFX_INVALID_HANDLE, screenshot_.c_str());
        requested_ = true;
    } else if (frame_ == frames_ + kScreenshotTimeoutFrames) {
        kast::log::error("Screenshot timed out");
        failed_ = true;
        kast::requestQuit();
    }
}

void FrameLimit::onScreenshotSaved(bool saved)
{
    saved_ = saved;
    kast::requestQuit();
}
